const fs = require("fs");
const files = ["a.txt","b.txt","c.txt"];
const rows = [];
let total = 0;
for (const f of files) {
  const raw = fs.readFileSync(f, "utf8");
  const nums = [...raw.matchAll(/-?\d[\d,]*/g)].map(m => m[0]);
  if (nums.length !== 1) throw new Error(f + ": expected exactly one number, got " + JSON.stringify(nums));
  const value = Number(nums[0].replace(/,/g, ""));
  if (!Number.isFinite(value)) throw new Error(f + ": not a finite number: " + nums[0]);
