  if (String(value) !== nums[0]) throw new Error(f + ": round-trip mismatch " + value + " vs " + nums[0]);
  // cross-check: the only digit run in the file is that number
  if (!new RegExp("(^|[^0-9])" + value + "([^0-9]|$)").test(raw)) throw new Error(f + ": value not uniquely anchored in text");
  total += value;
  rows.push({ file: f, label: raw.split(":").slice(0, -1).join(":"), value, bytes: Buffer.byteLength(raw) });
}
